## 5. Supabase Infrastructure & Persistence Topology

Habitex AI requires high relational consistency for inventory, multi-vector embeddings for spatial semantic search, and real-time pub/sub channels for viewport synchronization.

### Database DDL & Schema Definition

```sql
-- Enable necessary extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "vector";

-- 1. Scan Manifest Persistence
CREATE TABLE public.room_scans (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    client_runtime VARCHAR(32) NOT NULL, -- 'VisionOS' | 'WebXR'
    bounding_box JSONB NOT NULL,          -- Encapsulates min, max, center, extents
    planes JSONB NOT NULL,                -- Array of SpatialPlaneAnchor
    light_probe JSONB NOT NULL,           -- SH coefficients and illuminance metrics
    storage_mesh_path TEXT                -- Supabase Storage path for .ply / .usdz
);

-- 2. Spatial Asset Catalog (with pgvector for Semantic Search)
CREATE TABLE public.spatial_catalog_items (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    sku VARCHAR(64) UNIQUE NOT NULL,
    name TEXT NOT NULL,
    category VARCHAR(64) NOT NULL,
    dimensions_metric VECTOR(3) NOT NULL, -- [width, height, depth] in metres
    gltf_storage_path TEXT NOT NULL,      -- Optimized for Three.js
    usdz_storage_path TEXT NOT NULL,      -- Optimized for RealityKit / visionOS
    price_cents INT NOT NULL,
    currency VARCHAR(3) NOT NULL DEFAULT 'USD',
    in_stock BOOLEAN NOT NULL DEFAULT TRUE,
    retailer_id UUID NOT NULL,
    embedding VECTOR(768),                 -- Semantic embedding for design queries
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Index for spatial bounding lookups
CREATE INDEX idx_catalog_dimensions ON public.spatial_catalog_items USING gist (dimensions_metric);
CREATE INDEX idx_catalog_embedding ON public.spatial_catalog_items USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

-- 3. Collaborative Design Sessions
CREATE TABLE public.design_sessions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES auth.users(id),
    scan_id UUID NOT NULL REFERENCES public.room_scans(id),
    name TEXT NOT NULL,
    version INT NOT NULL DEFAULT 1,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Entity Instances in Spatial Graph (Current Scene State)
CREATE TABLE public.scene_entities (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    session_id UUID NOT NULL REFERENCES public.design_sessions(id) ON DELETE CASCADE,
    catalog_item_id UUID NOT NULL REFERENCES public.spatial_catalog_items(id),
    position VECTOR(3) NOT NULL,           -- [x, y, z] in metres
    rotation VECTOR(4) NOT NULL,           -- [w, x, y, z] Quaternion
    scale VECTOR(3) NOT NULL DEFAULT '[1,1,1]',
    material_overrides JSONB DEFAULT '{}'::jsonb,
    is_locked BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. Surface Overrides (Walls, Floors, Ceilings)
CREATE TABLE public.surface_modifications (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    session_id UUID NOT NULL REFERENCES public.design_sessions(id) ON DELETE CASCADE,
    plane_anchor_id TEXT NOT NULL,
    surface_type VARCHAR(16) NOT NULL,     -- 'wall' | 'floor' | 'ceiling'
    pbr_material JSONB NOT NULL,           -- Albedo, roughness, metallic, normal URLs
    applied_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(session_id, plane_anchor_id)
);
```

### Row Level Security (RLS) Policies

```sql
ALTER TABLE public.room_scans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.design_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.scene_entities ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.surface_modifications ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can fully manage their own room scans"
ON public.room_scans FOR ALL TO authenticated
USING (auth.uid() = user_id);

CREATE POLICY "Users can access their own design sessions"
ON public.design_sessions FOR ALL TO authenticated
USING (auth.uid() = user_id);

CREATE POLICY "Users can manage entities within their active sessions"
ON public.scene_entities FOR ALL TO authenticated
USING (
    session_id IN (
        SELECT id FROM public.design_sessions WHERE user_id = auth.uid()
    )
);

CREATE POLICY "Users can manage surface modifications in their sessions"
ON public.surface_modifications FOR ALL TO authenticated
USING (
    session_id IN (
        SELECT id FROM public.design_sessions WHERE user_id = auth.uid()
    )
);

-- Public Read-Only Access to the Furniture Catalog
ALTER TABLE public.spatial_catalog_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public Read Access for Catalog Items"
ON public.spatial_catalog_items FOR SELECT TO authenticated
USING (true);
```

