## 6. Next.js App Router Ingress and Realtime Synchronization

The Next.js App Router serves as the orchestration layer between the spatial client, the Supabase persistent store, and the `@google/genai` reasoning service.

### Route Handler: Direct Scan Ingestion & Validation

```ts
// app/api/spatial/scan/route.ts
import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { PhysicalRoomScanManifest } from "@/types/spatial";

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

export async function POST(req: NextRequest) {
  try {
    const authHeader = req.headers.get("authorization");
    if (!authHeader) {
      return NextResponse.json({ error: "Missing authorization bearer" }, { status: 401 });
    }

    const token = authHeader.replace("Bearer ", "");
    const { data: { user }, error: authError } = await supabase.auth.getUser(token);

    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized access" }, { status: 401 });
    }

    const payload = (await req.json()) as PhysicalRoomScanManifest;

    // Validate geometric integrity
    if (!payload.bounds || !payload.planes || payload.planes.length === 0) {
      return NextResponse.json({ error: "Invalid spatial scan: Incomplete boundaries" }, { status: 422 });
    }

    // Persist scan manifest within Supabase
    const { data: scanRecord, error: insertError } = await supabase
      .from("room_scans")
      .insert({
        user_id: user.id,
        client_runtime: payload.clientRuntime,
        bounding_box: payload.bounds,
        planes: payload.planes,
        light_probe: payload.lightProbe,
        storage_mesh_path: payload.rawMeshStorageKey ?? null
      })
      .select("id")
      .single();

    if (insertError) {
      return NextResponse.json({ error: insertError.message }, { status: 500 });
    }

    // Provision default design session
    const { data: sessionRecord, error: sessionError } = await supabase
      .from("design_sessions")
      .insert({
        user_id: user.id,
        scan_id: scanRecord.id,
        name: `Design - ${new Date().toLocaleDateString()}`
      })
      .select("id")
      .single();

    if (sessionError) {
      return NextResponse.json({ error: sessionError.message }, { status: 500 });
    }

    return NextResponse.json({
      scanId: scanRecord.id,
      sessionId: sessionRecord.id,
      status: "INITIALIZED"
    }, { status: 201 });

  } catch (error) {
    return NextResponse.json({ error: "Internal spatial ingestion error" }, { status: 500 });
  }
}
```

### Route Handler: Spatial Agent Action & Dispatch

```ts
// app/api/spatial/mutate/route.ts
import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { GoogleGenAI, Type } from "@google/genai";
import { Quaternion, Vector3D } from "@/types/spatial";

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

const ai = new GoogleGenAI({});

// Helper: Convert Y-axis degrees to Quaternion
function eulerYToQuaternion(degrees: number): Quaternion {
  const rad = (degrees * Math.PI) / 180;
  return [Math.cos(rad / 2), 0, Math.sin(rad / 2), 0];
}

export async function POST(req: NextRequest) {
  try {
    const { sessionId, prompt } = await req.json();

    // 1. Fetch current scene state and original scan bounds
    const { data: session, error: sessionErr } = await supabase
      .from("design_sessions")
      .select("*, room_scans(*)")
      .eq("id", sessionId)
      .single();

    if (sessionErr || !session) {
      return NextResponse.json({ error: "Spatial session not found" }, { status: 404 });
    }

    const scanContext = session.room_scans;

    // 2. Query Gemini with spatial tools
    const geminiResponse = await ai.models.generateContent({
      model: "gemini-3.7-flash",
      contents: [{ role: "user", parts: [{ text: prompt }] }],
      config: {
        systemInstruction: {
          parts: [{
            text: `Spatial agent for room ${sessionId}. Extents: ${JSON.stringify(scanContext.bounding_box.extents)}. Ensure collisions are avoided.`
          }]
        },
        tools: [{
          functionDeclarations: [
            {
              name: "place_furniture",
              description: "Insert a physical catalog item into the room.",
              parameters: {
                type: Type.OBJECT,
                properties: {
                  sku: { type: Type.STRING },
                  x: { type: Type.NUMBER },
                  y: { type: Type.NUMBER },
                  z: { type: Type.NUMBER },
                  rotationDegreesY: { type: Type.NUMBER }
                },
                required: ["sku", "x", "y", "z", "rotationDegreesY"]
              }
            }
          ]
        }]
      }
    });

    const functionCalls = geminiResponse.functionCalls;
    const executedMutations = [];

    if (functionCalls && functionCalls.length > 0) {
      for (const call of functionCalls) {
        if (call.name === "place_furniture") {
          const args = call.args as { sku: string; x: number; y: number; z: number; rotationDegreesY: number };

          // Verify item catalog details
          const { data: item } = await supabase
            .from("spatial_catalog_items")
            .select("id, gltf_storage_path, usdz_storage_path")
            .eq("sku", args.sku)
            .single();

          if (item) {
            const rotationQuat = eulerYToQuaternion(args.rotationDegreesY);
            const positionVec: Vector3D = [args.x, args.y, args.z];

            // Persist spatial entity to scene
            const { data: entity, error: entityErr } = await supabase
              .from("scene_entities")
              .insert({
                session_id: sessionId,
                catalog_item_id: item.id,
                position: positionVec,
                rotation: rotationQuat,
                scale: [1, 1, 1]
              })
              .select()
              .single();

            if (!entityErr && entity) {
              executedMutations.push({
                type: "ENTITY_PLACED",
                entityId: entity.id,
                sku: args.sku,
                position: positionVec,
                rotation: rotationQuat,
                assetUrls: {
                  gltf: item.gltf_storage_path,
                  usdz: item.usdz_storage_path
                }
              });
            }
          }
        }
      }
    }

    // 3. Broadcast execution outcome to client runtimes via Supabase Realtime channel
    const channel = supabase.channel(`room:${sessionId}:scene`);
    await channel.send({
      type: "broadcast",
      event: "scene_mutated",
      payload: {
        mutations: executedMutations,
        agentSummary: geminiResponse.text
      }
    });

    return NextResponse.json({
      status: "EXECUTED",
      agentText: geminiResponse.text,
      mutations: executedMutations
    });

  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}
