### TypeScript Client-Side Integration Hook (Three.js / WebXR)

```ts
// hooks/useSpatialSceneSync.ts
import { useEffect, useRef } from "react";
import { createClient, RealtimeChannel } from "@supabase/supabase-js";
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";

interface SpatialSyncProps {
  sessionId: string;
  threeScene: THREE.Scene;
  supabaseUrl: string;
  supabaseAnonKey: string;
}

export function useSpatialSceneSync({
  sessionId,
  threeScene,
  supabaseUrl,
  supabaseAnonKey
}: SpatialSyncProps) {
  const channelRef = useRef<RealtimeChannel | null>(null);
  const gltfLoader = useRef(new GLTFLoader());

  useEffect(() => {
    const supabase = createClient(supabaseUrl, supabaseAnonKey);
    const channelName = `room:${sessionId}:scene`;

    const channel = supabase.channel(channelName)
      .on("broadcast", { event: "scene_mutated" }, async (payload) => {
        const { mutations } = payload.payload;

        for (const mut of mutations) {
          if (mut.type === "ENTITY_PLACED") {
            // Load and instantiate GLB asset into Three.js scene
            gltfLoader.current.load(mut.assetUrls.gltf, (gltf) => {
              const model = gltf.scene;
              model.name = mut.entityId;

              // Set Metric Position [x, y, z]
              model.position.set(mut.position[0], mut.position[1], mut.position[2]);

              // Apply Hamilton Quaternion: Habitex [w, x, y, z] -> Three.js [x, y, z, w]
              model.quaternion.set(
                mut.rotation[1], // x
                mut.rotation[2], // y
                mut.rotation[3], // z
                mut.rotation[0]  // w
              );

              model.castShadow = true;
              model.receiveShadow = true;
              threeScene.add(model);
            });
          }
        }
      })
      .subscribe();

    channelRef.current = channel;

    return () => {
      channel.unsubscribe();
    };
  }, [sessionId, threeScene, supabaseUrl, supabaseAnonKey]);
}
