        transform: {
          position: se.position,
          rotation: se.rotation,
          scale: se.scale
        },
        boundingBox: se.bounding_box,
        clearanceBufferMeters: 0.35
      }))
    };

    // 2. Initialize Habitex Engine with Database Dependency Inversion
    const engine = new HabitexSpatialEngine({
      findCatalogItemBySku: async (sku: string) => {
        const { data } = await supabase
          .from('spatial_catalog_items')
          .select('*')
          .eq('sku', sku)
          .single();
        if (!data) return null;
        return {
          sku: data.sku,
          name: data.name,
          category: data.category,
          dimensionsMetric: data.dimensions_metric,
          priceCents: data.price_cents,
          currency: data.currency,
