### 3. Streaming Conversational Agent Endpoint (`app/api/agent/stream/route.ts`)

This is the central execution pipeline. It provides a real-time Server-Sent Events (SSE) stream using standard Web `ReadableStream` & `TransformStream`. 

It coordinates:
1. Interactive multi-turn conversation with `gemini-3.7-flash` using `@google/genai`.
2. Strict structural & mathematical SAT guardrail validation (`SpatialGuardrailsEngine`).
3. Execution error correction loops feeding spatial collisions directly back into the LLM.
4. Database state persistence via the atomic `commit_spatial_mutation_tx` stored procedure.
5. Realtime multi-client synchronization via Supabase Realtime CDC broadcast.

```typescript
import { NextRequest } from 'next/server';
import { GoogleGenAI, Content, Part } from '@google/genai';
import { createClientFromRequest, createAdminClient } from '@/src/lib/supabase/server';
import { habitexTools } from '@/src/agent/tools';
import { SpatialMath } from '@/src/spatial/math';
import { SpatialGuardrailsEngine } from '@/src/spatial/guardrails';
import {
  PhysicalRoomScanManifest,
  SceneGraphState,
  SpatialEntityInstance,
  Vector3D,
} from '@/src/types/spatial';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

// SSE Event Protocol Types
type StreamEventType =
  | 'thought'
  | 'tool_call'
  | 'guardrail_check'
  | 'scene_mutation'
  | 'inventory_result'
  | 'commentary'
  | 'error'
  | 'done';

function formatSSE(event: StreamEventType, data: Record<string, any>): Uint8Array {
  const encoder = new TextEncoder();
  return encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

export async function POST(req: NextRequest) {
  // Validate User Session via Supabase Auth
  const supabase = await createClientFromRequest();
  const { data: { user }, error: authError } = await supabase.auth.getUser();

  if (authError || !user) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const { sessionId, userMessage, conversationHistory = [] } = await req.json();

  if (!sessionId || !userMessage) {
    return new Response(JSON.stringify({ error: 'Missing required parameters: sessionId, userMessage' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  // Retrieve Design Session, Room Scan, and Active Scene State
  const { data: session, error: sessionError } = await supabase
    .from('design_sessions')
    .select(`
      id,
      user_id,
      version,
      environment_lighting,
      room_scans (*),
      scene_entities (*),
      surface_modifications (*)
    `)
    .eq('id', sessionId)
    .single();

  if (sessionError || !session || !session.room_scans) {
    return new Response(JSON.stringify({ error: 'Design session or associated scan manifest not found' }), {
      status: 404,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const scanData = session.room_scans as any;

  // Build In-Memory Spatial State Representation
  const scanManifest: PhysicalRoomScanManifest = {
    scanId: scanData.id,
    userId: scanData.user_id,
    capturedAt: scanData.created_at,
    clientRuntime: scanData.client_runtime,
    deviceHardware: scanData.device_hardware,
    bounds: scanData.bounding_box,
    planes: scanData.planes,
    lightProbe: scanData.light_probe,
  };

  const activeScene: SceneGraphState = {
    version: session.version,
    sessionId: session.id,
    environmentLighting: session.environment_lighting as any,
    wallSurfaceModifications: (session.surface_modifications || []).map((sm: any) => ({
      planeAnchorId: sm.plane_anchor_id,
      pbrMaterial: sm.pbr_material,
    })),
    entities: (session.scene_entities || []).map((se: any) => {
      const pos = Array.isArray(se.position) ? se.position : JSON.parse(se.position);
      const rot = Array.isArray(se.rotation) ? se.rotation : JSON.parse(se.rotation);
      const scl = se.scale ? (Array.isArray(se.scale) ? se.scale : JSON.parse(se.scale)) : [1, 1, 1];
      return {
        instanceId: se.id,
        catalogItemId: se.catalog_item_id,
        sku: se.catalog_item_id,
        name: 'Scene Placed Entity',
        transform: { position: pos, rotation: rot, scale: scl },
        boundingBox: { min: [-0.5, 0, -0.5], max: [0.5, 1, 0.5], center: [0, 0.5, 0], extents: [0.5, 0.5, 0.5] },
        clearanceBufferMeters: 0.35,
      };
    }),
  };

  // Construct Next.js ReadableStream Transform Pipeline
  const { readable, writable } = new TransformStream();
  const writer = writable.getWriter();

  // Run the asynchronous agent reasoning loop
  (async () => {
    const adminSupabase = createAdminClient();
    const ai = new GoogleGenAI({});

    const wallPlanes = scanManifest.planes.filter((p) => p.semanticType === 'wall');
    const floorPlanes = scanManifest.planes.filter((p) => p.semanticType === 'floor');
    const openings = scanManifest.planes.filter((p) => p.semanticType === 'door' || p.semanticType === 'window');

    const systemInstruction = `
You are Habitex AI, an autonomous interior architect and spatial computing agent for VisionOS & WebXR.
Coordinate System: Right-handed metric system (+X: Right, +Y: Up, +Z: Outward).

PHYSICAL CONSTRAINTS:
- Room Metric Bounds: Min [${scanManifest.bounds.min.join(', ')}] | Max [${scanManifest.bounds.max.join(', ')}]
- Structural Walls: ${wallPlanes.map((w) => `'${w.id}'`).join(', ')}
- Floors Detected: ${floorPlanes.length}
- Doorways & Clearances: ${openings.map((o) => `${o.semanticType} ('${o.id}')`).join(', ')}

CURRENT SCENE ENTITIES (${activeScene.entities.length}):
${activeScene.entities.map((e) => `- ${e.name} [ID: ${e.instanceId}]: pos=[${e.transform.position.join(', ')}]`).join('\n') || 'None'}

SURFACE MODS:
${activeScene.wallSurfaceModifications.map((m) => `- Wall '${m.planeAnchorId}': ${m.pbrMaterial.materialCategory}`).join('\n') || 'Original'}

OPERATIONAL PRINCIPLES:
1. Always test catalog items before placing using 'search_inventory' or target dimensions.
2. Floor furniture must have position Y = 0.00.
3. Obey clearance buffers around doorways and corridors.
4. If a tool reports a GUARDRAIL_VIOLATION, review the suggested correction and call the tool again with the adjusted transform.
`;

    const contents: Content[] = [
      ...conversationHistory,
      { role: 'user', parts: [{ text: userMessage }] },
    ];

    const entitiesToInsertBatch: any[] = [];
    const surfacesToUpsertBatch: any[] = [];

    const MAX_TOOL_HOPS = 6;
    let iteration = 0;

    try {
      await writer.write(
        formatSSE('thought', { message: 'Analyzing room scan and spatial constraints...' })
      );

      while (iteration < MAX_TOOL_HOPS) {
        iteration++;

        const response = await ai.models.generateContent({
          model: 'gemini-3.7-flash',
          contents,
          config: {
            systemInstruction: { parts: [{ text: systemInstruction }] },
            tools: [{ functionDeclarations: habitexTools }],
            temperature: 0.15,
          },
        });

        const candidate = response.candidates?.[0];
        if (!candidate) {
          throw new Error('Spatial agent generated empty response.');
        }

        contents.push(candidate.content);

        const functionCalls = candidate.content.parts.filter((p) => p.functionCall);

        // If no tool call, stream commentary to client and exit loop
        if (functionCalls.length === 0) {
          const finalMessage = response.text || 'Layout updated according to preferences.';
          await writer.write(formatSSE('commentary', { text: finalMessage }));
          break;
        }

        // Process function calls
        const toolResponseParts: Part[] = [];

        for (const part of functionCalls) {
          const call = part.functionCall!;
          const args = call.args as Record<string, any>;

          await writer.write(
            formatSSE('tool_call', { tool: call.name, parameters: args })
          );

          let toolResult: any;

          switch (call.name) {
            case 'place_model': {
              const { sku, position, rotationDegreesY, targetWallId, clearanceBufferMeters } = args;

              // Query item details from catalog
              const { data: item } = await supabase
                .from('spatial_catalog_items')
                .select('*')
                .eq('sku', sku)
                .single();

              if (!item) {
                toolResult = { status: 'ERROR', message: `SKU '${sku}' not found in catalog.` };
                break;
              }

              const dim = Array.isArray(item.dimensions_metric)
                ? (item.dimensions_metric as [number, number, number])
                : (JSON.parse(item.dimensions_metric as unknown as string) as [number, number, number]);

              const tentativeEntity: SpatialEntityInstance = {
                instanceId: `ent_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
                catalogItemId: item.id,
                sku: item.sku,
                name: item.name,
                transform: {
                  position: position as Vector3D,
                  rotation: SpatialMath.quaternionFromEulerY(rotationDegreesY || 0),
                  scale: [1, 1, 1],
                },
                boundingBox: {
                  min: [-dim[0] / 2, 0, -dim[2] / 2],
                  max: [dim[0] / 2, dim[1], dim[2] / 2],
                  center: [0, dim[1] / 2, 0],
                  extents: [dim[0] / 2, dim[1] / 2, dim[2] / 2],
                },
                clearanceBufferMeters: clearanceBufferMeters ?? 0.35,
                isWallMounted: false,
              };

              // Run mathematical 3D SAT collision check
              const validation = SpatialGuardrailsEngine.validateEntityPlacement(
                tentativeEntity,
                scanManifest,
                activeScene,
                targetWallId
              );

              await writer.write(
                formatSSE('guardrail_check', {
                  sku,
                  status: validation.valid ? 'PASSED' : 'FAILED',
                  code: validation.code,
                  message: validation.message,
                  correction: validation.suggestedCorrection,
                })
              );

              if (!validation.valid) {
                toolResult = {
                  status: 'GUARDRAIL_VIOLATION',
                  code: validation.code,
                  message: validation.message,
                  suggestedCorrection: validation.suggestedCorrection,
                };
              } else {
                activeScene.entities.push(tentativeEntity);
                entitiesToInsertBatch.push({
                  catalog_item_id: item.id,
                  position: tentativeEntity.transform.position,
                  rotation: tentativeEntity.transform.rotation,
                  scale: tentativeEntity.transform.scale,
                });

                toolResult = {
                  status: 'SUCCESS',
                  instanceId: tentativeEntity.instanceId,
                  name: item.name,
                  position: tentativeEntity.transform.position,
                };

                await writer.write(
                  formatSSE('scene_mutation', {
                    action: 'ENTITY_ADDED',
                    entity: tentativeEntity,
                    assets: {
                      gltf: item.gltf_storage_path,
                      usdz: item.usdz_storage_path,
                    },
                  })
                );
              }
              break;
            }

            case 'adjust_lighting': {
              const { ambientLightColorHex, ambientIntensityLumens, directionalRigs } = args;
              const cleanHex = ambientLightColorHex.replace('#', '');
              const r = parseInt(cleanHex.substring(0, 2), 16) / 255.0;
              const g = parseInt(cleanHex.substring(2, 4), 16) / 255.0;
              const b = parseInt(cleanHex.substring(4, 6), 16) / 255.0;

              activeScene.environmentLighting = {
                overrideEnabled: true,
                ambientLightColor: [r, g, b],
                ambientIntensity: ambientIntensityLumens,
                directionalRig: (directionalRigs || []).map((d: any, idx: number) => ({
                  id: `light_${idx}`,
                  position: [0, 2.5, 0],
                  direction: d.direction,
                  intensity: d.intensityLux,
                  castShadows: d.castShadows,
                })),
              };

              // Persist lighting mutation to design session
              await adminSupabase
                .from('design_sessions')
                .update({ environment_lighting: activeScene.environmentLighting })
                .eq('id', sessionId);

              toolResult = { status: 'SUCCESS', lighting: activeScene.environmentLighting };

              await writer.write(
                formatSSE('scene_mutation', { action: 'LIGHTING_CHANGED', lighting: activeScene.environmentLighting })
              );
              break;
            }

            case 'set_surface_material': {
              const { planeAnchorId, materialCategory, albedoHex, roughness, metallic } = args;
              const targetPlane = scanManifest.planes.find((p) => p.id === planeAnchorId);

              if (!targetPlane) {
                toolResult = { status: 'ERROR', message: `Plane '${planeAnchorId}' does not exist.` };
                break;
              }

              const pbrMaterial = {
                materialId: `mat_${materialCategory}`,
                name: materialCategory,
                albedoFactor: [1, 1, 1, 1] as [number, number, number, number],
                roughnessFactor: roughness,
                metallicFactor: metallic,
                albedoHex,
                uvScale: [1.0, 1.0] as [number, number],
              };

              surfacesToUpsertBatch.push({
                plane_anchor_id: planeAnchorId,
                surface_type: targetPlane.semanticType,
                pbr_material: pbrMaterial,
              });

              toolResult = { status: 'SUCCESS', planeAnchorId, pbrMaterial };

              await writer.write(
                formatSSE('scene_mutation', { action: 'SURFACE_MODIFIED', planeAnchorId, pbrMaterial })
              );
              break;
            }

            case 'search_inventory': {
              const { query, maxBudgetUsd, maxDimensions } = args;

              let dbQuery = adminSupabase
                .from('spatial_catalog_items')
                .select('sku, name, category, price_cents, dimensions_metric, gltf_storage_path, usdz_storage_path')
                .ilike('name', `%${query}%`)
                .eq('in_stock', true);

              if (maxBudgetUsd) {
                dbQuery = dbQuery.lte('price_cents', maxBudgetUsd * 100);
              }

              const { data: matches } = await dbQuery.limit(4);

              toolResult = {
                count: matches?.length || 0,
                items: (matches || []).map((m: any) => ({
                  sku: m.sku,
                  name: m.name,
                  priceUsd: (m.price_cents / 100).toFixed(2),
                  dimensionsMeters: m.dimensions_metric,
                })),
              };

              await writer.write(formatSSE('inventory_result', { query, items: toolResult.items }));
              break;
            }

            default:
              toolResult = { status: 'ERROR', message: `Unhandled agent tool: ${call.name}` };
          }

          toolResponseParts.push({
            functionResponse: {
              name: call.name,
              response: toolResult,
            },
          });
        }

        contents.push({ role: 'user', parts: toolResponseParts });
      }

      // Atomically commit batch spatial mutations via Supabase Stored Procedure
      if (entitiesToInsertBatch.length > 0 || surfacesToUpsertBatch.length > 0) {
        const { data: txResult, error: txError } = await supabase.rpc('commit_spatial_mutation_tx', {
          p_session_id: sessionId,
          p_entities: entitiesToInsertBatch,
          p_surfaces: surfacesToUpsertBatch,
        });

        if (txError) {
          console.error('[Transaction Error RPC]:', txError);
          await writer.write(formatSSE('error', { message: 'Database commit failed', details: txError.message }));
        } else {
          // Broadcast delta over Supabase Realtime Channel
          const channel = adminSupabase.channel(`room:${sessionId}:scene`);
          await channel.send({
            type: 'broadcast',
            event: 'scene_committed',
            payload: {
              sessionId,
              version: activeScene.version + 1,
              placedCount: entitiesToInsertBatch.length,
              surfaceCount: surfacesToUpsertBatch.length,
            },
          });
        }
      }

      await writer.write(formatSSE('done', { sessionId, turnComplete: true }));
    } catch (streamError: any) {
      console.error('[Streaming Error]:', streamError);
      await writer.write(formatSSE('error', { message: streamError.message || 'Stream processing error' }));
    } finally {
      await writer.close();
    }
  })();

  return new Response(readable, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      'Connection': 'keep-alive',
      'X-Accel-Buffering': 'no',
    },
  });
}
