### 4. Inventory Vector Search Endpoint (`app/api/inventory/search/route.ts`)

Performs spatial-bounded semantic searches against `spatial_catalog_items`. Computes the text embedding via `@google/genai` (`text-embedding-004`), then executes the `match_spatial_catalog_items` PostgreSQL RPC function to enforce dimensional and budgetary envelope filtering.

```typescript
import { NextRequest, NextResponse } from 'next/server';
import { GoogleGenAI } from '@google/genai';
import { createClientFromRequest } from '@/src/lib/supabase/server';
import { CatalogCategory } from '@/types/supabase';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

interface SearchRequestPayload {
  query: string;
  category?: CatalogCategory;
  maxDimensionsMetric?: [width: number, height: number, depth: number];
  maxPriceCents?: number;
  matchThreshold?: number;
  limit?: number;
}

export async function POST(req: NextRequest) {
  try {
    const supabase = await createClientFromRequest();
    const { data: { user }, error: authError } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const payload: SearchRequestPayload = await req.json();
    const {
      query,
      category,
      maxDimensionsMetric,
      maxPriceCents,
      matchThreshold = 0.4,
      limit = 8,
    } = payload;

    if (!query || typeof query !== 'string') {
      return NextResponse.json({ error: 'A text search query is required.' }, { status: 400 });
    }

    // Generate 768-dimensional text embedding via Google GenAI SDK
    const ai = new GoogleGenAI({});
    const embeddingResponse = await ai.models.embedContent({
      model: 'text-embedding-004',
      contents: query,
    });

    const embeddingValues = embeddingResponse.embedding?.values;
    if (!embeddingValues || embeddingValues.length === 0) {
      return NextResponse.json({ error: 'Failed to generate embedding for query' }, { status: 500 });
    }

    // Format metrics into PostgreSQL vector string format: [x,y,z]
    const queryEmbeddingStr = `[${embeddingValues.join(',')}]`;
    const maxDimStr = maxDimensionsMetric ? `[${maxDimensionsMetric.join(',')}]` : null;

    // Invoke pgvector cosine match RPC with spatial constraints
    const { data: matchedItems, error: rpcError } = await supabase.rpc('match_spatial_catalog_items', {
      query_embedding: queryEmbeddingStr,
      match_threshold: matchThreshold,
      match_count: limit,
      filter_category: category || null,
      max_price_cents: maxPriceCents || null,
      max_dimensions: maxDimStr,
    });

    if (rpcError) {
      console.error('[Inventory Vector Search RPC Failed]:', rpcError);
      return NextResponse.json({ error: 'Catalog match execution error', details: rpcError.message }, { status: 500 });
    }

    // Format response payload for 3D Viewers (VisionOS & Three.js / WebXR)
    const formattedResults = (matchedItems || []).map((item) => {
      const dimensions = typeof item.dimensions_metric === 'string'
        ? JSON.parse(item.dimensions_metric)
        : item.dimensions_metric;

      return {
        id: item.id,
        sku: item.sku,
        name: item.name,
        description: item.description,
        category: item.category,
        dimensionsMetric: dimensions,
        pricing: {
          priceCents: item.price_cents,
          currency: item.currency,
          formattedPrice: `$${(item.price_cents / 100).toFixed(2)}`,
        },
        assets: {
          gltfUrl: item.gltf_storage_path,
          usdzUrl: item.usdz_storage_path,
        },
        retailerName: item.retailer_name,
        similarityScore: item.similarity,
      };
    });

    return NextResponse.json({
      success: true,
      query,
      count: formattedResults.length,
      items: formattedResults,
    });
  } catch (err: any) {
    console.error('[Inventory Search Fatal]:', err);
    return NextResponse.json({ error: 'Internal server error during search', details: err.message }, { status: 500 });
  }
}
