### 2. Unified Scene Graph State Manager (`src/spatial/store/scene-store.ts`)

A Zustand store with Immer integration for state updates, optimistic 6DOF manipulation, agent ghosting, and conflict resolution between user actions and agent streams.

```typescript
import { create } from 'zustand';
import { immer } from 'zustand/middleware/immer';
import {
  ClientSpatialEntity,
  ClientSurfaceModification,
  ClientEnvironmentLighting,
  DetectedPlaneAnchor,
  Transform3D,
  Vector3Tuple,
  QuaternionTuple,
} from '@/src/types/spatial-client';

interface SceneState {
  sessionId: string | null;
  version: number;
  clientRuntime: 'WebXR' | 'VisionOS' | 'Desktop';
  isXRActive: boolean;
  selectedEntityId: string | null;
  planes: Map<string, DetectedPlaneAnchor>;
  entities: Map<string, ClientSpatialEntity>;
  surfaceModifications: Map<string, ClientSurfaceModification>;
  lighting: ClientEnvironmentLighting;

  // Interaction and Collaboration Controls
  activeGizmoMode: 'translate' | 'rotate' | 'none';
  agentIsReasoning: boolean;
  activeTurnCommentary: string | null;

  // Actions
  initializeSession: (sessionId: string, planes: DetectedPlaneAnchor[], initialLighting?: ClientEnvironmentLighting) => void;
  setClientRuntime: (runtime: 'WebXR' | 'VisionOS' | 'Desktop') => void;
  setXRActive: (active: boolean) => void;
  selectEntity: (id: string | null) => void;
  setGizmoMode: (mode: 'translate' | 'rotate' | 'none') => void;

  // Entity Operations
  upsertEntity: (entity: ClientSpatialEntity) => void;
  stageGhostEntity: (entity: ClientSpatialEntity) => void;
  commitGhostEntity: (instanceId: string) => void;
  removeEntity: (instanceId: string) => void;
  updateEntityTransformOptimistic: (instanceId: string, transform: Partial<Transform3D>) => void;
  setEntityTargetTransform: (instanceId: string, transform: Transform3D) => void;
  setEntityLock: (instanceId: string, locked: boolean, lockedBy?: 'user' | 'agent' | 'peer') => void;

  // Surfaces and Lighting
  applySurfaceModification: (mod: ClientSurfaceModification) => void;
  updateLighting: (lighting: Partial<ClientEnvironmentLighting>) => void;

  // Agent State Integration
  setAgentReasoning: (isReasoning: boolean, commentary?: string | null) => void;
  reconcileRemoteState: (version: number, entities: ClientSpatialEntity[], surfaces: ClientSurfaceModification[]) => void;
}

export const useSceneStore = create<SceneState>()(
  immer((set, get) => ({
    sessionId: null,
    version: 1,
    clientRuntime: 'WebXR',
    isXRActive: false,
    selectedEntityId: null,
    planes: new Map(),
    entities: new Map(),
    surfaceModifications: new Map(),
    lighting: {
      overrideEnabled: false,
      ambientLightColor: [1.0, 1.0, 1.0],
      ambientIntensity: 800,
      directionalRig: [],
    },
    activeGizmoMode: 'none',
    agentIsReasoning: false,
    activeTurnCommentary: null,

    initializeSession: (sessionId, planesArray, initialLighting) => {
      set((state) => {
        state.sessionId = sessionId;
        state.planes.clear();
        planesArray.forEach((p) => state.planes.set(p.id, p));
        if (initialLighting) {
          state.lighting = initialLighting;
        }
      });
    },

    setClientRuntime: (runtime) => set({ clientRuntime: runtime }),
    setXRActive: (active) => set({ isXRActive: active }),
    selectEntity: (id) => set({ selectedEntityId: id }),
    setGizmoMode: (mode) => set({ activeGizmoMode: mode }),

    upsertEntity: (entity) => {
      set((state) => {
        state.entities.set(entity.instanceId, entity);
      });
    },

    stageGhostEntity: (entity) => {
      set((state) => {
        state.entities.set(entity.instanceId, { ...entity, isGhost: true, isLocked: true, lockedBy: 'agent' });
      });
    },

    commitGhostEntity: (instanceId) => {
      set((state) => {
        const ent = state.entities.get(instanceId);
        if (ent) {
          ent.isGhost = false;
          ent.isLocked = false;
          ent.lockedBy = undefined;
        }
      });
    },

    removeEntity: (instanceId) => {
      set((state) => {
        state.entities.delete(instanceId);
        if (state.selectedEntityId === instanceId) {
          state.selectedEntityId = null;
        }
      });
    },

    updateEntityTransformOptimistic: (instanceId, partialTransform) => {
      set((state) => {
        const ent = state.entities.get(instanceId);
        if (ent) {
          if (partialTransform.position) ent.transform.position = partialTransform.position;
          if (partialTransform.rotation) ent.transform.rotation = partialTransform.rotation;
          if (partialTransform.scale) ent.transform.scale = partialTransform.scale;
        }
      });
    },

    setEntityTargetTransform: (instanceId, targetTransform) => {
      set((state) => {
        const ent = state.entities.get(instanceId);
        if (ent) {
          ent.targetTransform = targetTransform;
        }
      });
    },

    setEntityLock: (instanceId, locked, lockedBy) => {
      set((state) => {
        const ent = state.entities.get(instanceId);
        if (ent) {
          ent.isLocked = locked;
          ent.lockedBy = lockedBy;
        }
      });
    },

    applySurfaceModification: (mod) => {
      set((state) => {
        state.surfaceModifications.set(mod.planeAnchorId, mod);
      });
    },

    updateLighting: (partialLighting) => {
      set((state) => {
        Object.assign(state.lighting, partialLighting);
      });
    },

    setAgentReasoning: (isReasoning, commentary = null) => {
      set((state) => {
        state.agentIsReasoning = isReasoning;
        state.activeTurnCommentary = commentary;
      });
    },

    reconcileRemoteState: (version, remoteEntities, remoteSurfaces) => {
      set((state) => {
        // Drop reconciliation if client has higher optimistic version
        if (version < state.version) return;
        state.version = version;

        // Clean out ephemeral ghost entities that were rejected or replaced
        for (const [id, entity] of state.entities.entries()) {
          if (entity.isGhost && !remoteEntities.some((r) => r.instanceId === id)) {
            state.entities.delete(id);
          }
        }

        // Reconcile entities: preserve ongoing local user transforms
        remoteEntities.forEach((remoteEnt) => {
          const local = state.entities.get(remoteEnt.instanceId);
          if (!local) {
            state.entities.set(remoteEnt.instanceId, remoteEnt);
          } else if (local.isLocked && local.lockedBy === 'user') {
            // User is actively manipulating; preserve optimistic transform
            local.catalogItemId = remoteEnt.catalogItemId;
            local.sku = remoteEnt.sku;
            local.name = remoteEnt.name;
          } else {
            // Apply server transform as target for slerp/lerp smoothing
            local.targetTransform = remoteEnt.transform;
            local.boundingBox = remoteEnt.boundingBox;
            local.clearanceBufferMeters = remoteEnt.clearanceBufferMeters;
            local.isGhost = false;
          }
        });

        // Reconcile surface modifications
        remoteSurfaces.forEach((surf) => {
          state.surfaceModifications.set(surf.planeAnchorId, surf);
        });
      });
    },
  }))
);
