### 3. Progressive Asset Loader & VisionOS Pipeline (`src/spatial/loaders/asset-pipeline.ts`)

Implements a single-instance Three.js asset pipeline featuring Meshopt decompression, Draco decoding, hardware texture processing (KTX2), and a Web-to-VisionOS QuickLook USDZ fallback mechanism.

```typescript
import * as THREE from 'three';
import { GLTFLoader, GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';
import { KTX2Loader } from 'three/examples/jsm/loaders/KTX2Loader.js';

class SpatialAssetPipeline {
  private static instance: SpatialAssetPipeline;
  private gltfLoader: GLTFLoader;
  private textureLoader: THREE.TextureLoader;
  private ktx2Loader: KTX2Loader | null = null;
  private modelCache = new Map<string, THREE.Group>();
  private textureCache = new Map<string, THREE.Texture>();
  private loadingPromises = new Map<string, Promise<THREE.Group>>();

  private constructor() {
    this.gltfLoader = new GLTFLoader();
    this.textureLoader = new THREE.TextureLoader();

    // 1. Setup Google Draco Geometry Compression Decoder
    const dracoLoader = new DRACOLoader();
    dracoLoader.setDecoderPath('https://www.gstatic.com/draco/versioned/decoders/1.5.6/');
    dracoLoader.setDecoderConfig({ type: 'js' });
    this.gltfLoader.setDRACOLoader(dracoLoader);

    // 2. Setup Meshopt Decoder for compact transmission
    this.gltfLoader.setMeshoptDecoder(MeshoptDecoder);
  }

  public static getInstance(): SpatialAssetPipeline {
    if (!SpatialAssetPipeline.instance) {
      SpatialAssetPipeline.instance = new SpatialAssetPipeline();
    }
    return SpatialAssetPipeline.instance;
  }

  public initKTX2(renderer: THREE.WebGLRenderer) {
    if (!this.ktx2Loader) {
      this.ktx2Loader = new KTX2Loader();
      this.ktx2Loader.setTranscoderPath('https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/libs/basis/');
      this.ktx2Loader.detectSupport(renderer);
      this.gltfLoader.setKTX2Loader(this.ktx2Loader);
    }
  }

  /**
   * Load and cache GLTF/GLB models with automatic memory cloning
   */
  public async loadGLB(url: string, onProgress?: (percent: number) => void): Promise<THREE.Group> {
    if (this.modelCache.has(url)) {
      return this.modelCache.get(url)!.clone(true);
    }

    if (this.loadingPromises.has(url)) {
      const base = await this.loadingPromises.get(url)!;
      return base.clone(true);
    }

    const loadPromise = new Promise<THREE.Group>((resolve, reject) => {
      this.gltfLoader.load(
        url,
        (gltf: GLTF) => {
          const root = gltf.scene;

          // Configure shadows and PBR settings across meshes
          root.traverse((child) => {
            if ((child as THREE.Mesh).isMesh) {
              const mesh = child as THREE.Mesh;
              mesh.castShadow = true;
              mesh.receiveShadow = true;
              if (mesh.material) {
                const mat = mesh.material as THREE.MeshStandardMaterial;
                mat.envMapIntensity = 1.0;
                mat.needsUpdate = true;
              }
            }
          });

          this.modelCache.set(url, root);
          this.loadingPromises.delete(url);
          resolve(root.clone(true));
        },
        (xhr) => {
          if (xhr.lengthComputable && onProgress) {
            onProgress(Math.round((xhr.loaded / xhr.total) * 100));
          }
        },
        (error) => {
          this.loadingPromises.delete(url);
          console.error(`[SpatialAssetPipeline] Failed to load 3D GLB: ${url}`, error);
          reject(error);
        }
      );
    });

    this.loadingPromises.set(url, loadPromise);
    return loadPromise;
  }

  /**
   * Load and cache PBR textures with metric UV repeating
   */
  public async loadPBRTexture(url: string, uvScale: [number, number] = [1, 1]): Promise<THREE.Texture> {
    const cacheKey = `${url}_${uvScale[0]}_${uvScale[1]}`;
    if (this.textureCache.has(cacheKey)) {
      return this.textureCache.get(cacheKey)!;
    }

    return new Promise((resolve, reject) => {
      this.textureLoader.load(
        url,
        (texture) => {
          texture.wrapS = THREE.RepeatWrapping;
          texture.wrapT = THREE.RepeatWrapping;
          texture.repeat.set(uvScale[0], uvScale[1]);
          texture.colorSpace = THREE.SRGBColorSpace;
          texture.needsUpdate = true;
          this.textureCache.set(cacheKey, texture);
          resolve(texture);
        },
        undefined,
        (err) => reject(err)
      );
    });
  }

  /**
   * Trigger native AR Quick Look on Apple Vision Pro / iOS Safari
   */
  public launchVisionOSQuickLook(usdzUrl: string) {
    const anchor = document.createElement('a');
    anchor.setAttribute('rel', 'ar');
    anchor.setAttribute('href', usdzUrl);
    anchor.appendChild(document.createElement('img'));
    document.body.appendChild(anchor);
    anchor.click();
    document.body.removeChild(anchor);
  }
}

export const assetPipeline = SpatialAssetPipeline.getInstance();
```

