### 4. Supabase Realtime & Agent SSE Stream Client Hooks

#### A. Multi-Client Scene Graph Synchronizer (`src/spatial/hooks/use-scene-graph-sync.ts`)

Connects to Supabase Realtime channels for CDC events and atomic transaction broadcasts, and pushes user-initiated 6DOF transforms to remote collaborators.

```typescript
'use client';

import { useEffect, useRef, useCallback } from 'react';
import { createBrowserClient } from '@supabase/ssr';
import { useSceneStore } from '@/src/spatial/store/scene-store';
import { ClientSpatialEntity, ClientSurfaceModification, Transform3D } from '@/src/types/spatial-client';
import { Database } from '@/types/supabase';

export function useSceneGraphSync(sessionId: string | null) {
  const supabaseRef = useRef(
    createBrowserClient<Database>(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    )
  );

  const channelRef = useRef<any>(null);
  const reconcileRemoteState = useSceneStore((s) => s.reconcileRemoteState);
  const setEntityTargetTransform = useSceneStore((s) => s.setEntityTargetTransform);
  const setEntityLock = useSceneStore((s) => s.setEntityLock);

  // Synchronize incoming authoritative transactions from the Postgres RPC
  const fetchAuthoritativeScene = useCallback(async () => {
    if (!sessionId) return;
    const supabase = supabaseRef.current;

    const { data: sessionData, error } = await supabase
      .from('design_sessions')
      .select(`
        version,
        scene_entities (*),
        surface_modifications (*)
      `)
      .eq('id', sessionId)
      .single();

    if (error || !sessionData) {
      console.error('[SceneSync] Error querying authoritative state:', error);
      return;
    }

    const entities: ClientSpatialEntity[] = (sessionData.scene_entities || []).map((se: any) => ({
      instanceId: se.id,
      catalogItemId: se.catalog_item_id,
      sku: se.catalog_item_id,
      name: 'Scene Placed Entity',
      transform: {
        position: Array.isArray(se.position) ? se.position : JSON.parse(se.position),
        rotation: Array.isArray(se.rotation) ? se.rotation : JSON.parse(se.rotation),
        scale: se.scale ? (Array.isArray(se.scale) ? se.scale : JSON.parse(se.scale)) : [1, 1, 1],
      },
      boundingBox: {
        min: [-0.5, 0, -0.5],
        max: [0.5, 1, 0.5],
        center: [0, 0.5, 0],
        extents: [0.5, 0.5, 0.5],
      },
      clearanceBufferMeters: 0.35,
      isLocked: false,
      assets: {
        gltfUrl: `/api/storage/models/${se.catalog_item_id}.glb`,
      },
    }));

    const surfaces: ClientSurfaceModification[] = (sessionData.surface_modifications || []).map((sm: any) => ({
      planeAnchorId: sm.plane_anchor_id,
      surfaceType: sm.surface_type,
      pbrMaterial: sm.pbr_material,
    }));

    reconcileRemoteState(sessionData.version, entities, surfaces);
  }, [sessionId, reconcileRemoteState]);

  useEffect(() => {
    if (!sessionId) return;
    const supabase = supabaseRef.current;

    // Initial hydration
    fetchAuthoritativeScene();

    // Subscribe to Broadcast + Postgres CDC channel
    const channel = supabase.channel(`room:${sessionId}:scene`, {
      config: { broadcast: { self: false } },
    });

    channel
      // 1. Transactional RPC commit broadcast
      .on('broadcast', { event: 'scene_committed' }, () => {
        fetchAuthoritativeScene();
      })
      // 2. Real-time 6DOF user peer manipulation (60Hz throttled transforms)
      .on('broadcast', { event: 'entity_transform_peer' }, ({ payload }) => {
        const { instanceId, transform, userId } = payload;
        setEntityLock(instanceId, true, 'peer');
        setEntityTargetTransform(instanceId, transform);
      })
      // 3. Peer interaction unlock event
      .on('broadcast', { event: 'entity_transform_released' }, ({ payload }) => {
        const { instanceId } = payload;
        setEntityLock(instanceId, false);
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log(`[SceneSync] Connected to spatial channel: room:${sessionId}:scene`);
        }
      });

    channelRef.current = channel;

    return () => {
      supabase.removeChannel(channel);
    };
  }, [sessionId, fetchAuthoritativeScene, setEntityTargetTransform, setEntityLock]);

  // Broadcast throttled local 6DOF transform updates
  const broadcastLocalTransform = useCallback((instanceId: string, transform: Transform3D) => {
    if (channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'entity_transform_peer',
        payload: { instanceId, transform },
      });
    }
  }, []);

  const broadcastReleaseTransform = useCallback((instanceId: string) => {
    if (channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'entity_transform_released',
        payload: { instanceId },
      });
    }
  }, []);

  return { broadcastLocalTransform, broadcastReleaseTransform, refreshScene: fetchAuthoritativeScene };
}
```

#### B. Agent Spatial SSE Pipeline Consumer (`src/spatial/hooks/use-agent-stream.ts`)

Parses Server-Sent Events from `/api/agent/stream`. Renders intermediate ghost models during LLM reasoning passes and commits them upon guardrail validation.

```typescript
'use client';

import { useState, useCallback } from 'react';
import { useSceneStore } from '@/src/spatial/store/scene-store';
import { ClientSpatialEntity } from '@/src/types/spatial-client';

export function useAgentSpatialStream(sessionId: string | null) {
  const [isStreaming, setIsStreaming] = useState(false);
  const [streamCommentary, setStreamCommentary] = useState<string>('');

  const stageGhostEntity = useSceneStore((s) => s.stageGhostEntity);
  const commitGhostEntity = useSceneStore((s) => s.commitGhostEntity);
  const updateLighting = useSceneStore((s) => s.updateLighting);
  const applySurfaceModification = useSceneStore((s) => s.applySurfaceModification);
  const setAgentReasoning = useSceneStore((s) => s.setAgentReasoning);

  const sendAgentMessage = useCallback(async (userMessage: string, conversationHistory: any[] = []) => {
    if (!sessionId || !userMessage.trim()) return;

    setIsStreaming(true);
    setAgentReasoning(true, 'Initializing spatial reasoning...');
    setStreamCommentary('');

    try {
      const response = await fetch('/api/agent/stream', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId,
          userMessage,
          conversationHistory,
        }),
      });

      if (!response.ok || !response.body) {
        throw new Error(`Failed to initialize stream: HTTP ${response.status}`);
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder('utf-8');
      let buffer = '';

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const events = buffer.split('\n\n');
        buffer = events.pop() || ''; // Keep partial chunks in buffer

        for (const rawEvent of events) {
          if (!rawEvent.trim()) continue;

          const lines = rawEvent.split('\n');
          let eventType = '';
          let dataStr = '';

          for (const line of lines) {
            if (line.startsWith('event: ')) {
              eventType = line.substring(7).trim();
            } else if (line.startsWith('data: ')) {
              dataStr = line.substring(6).trim();
            }
          }

          if (!eventType || !dataStr) continue;
          const payload = JSON.parse(dataStr);

          switch (eventType) {
            case 'thought':
              setAgentReasoning(true, payload.message);
              break;

            case 'guardrail_check':
              if (payload.status === 'PASSED') {
                setAgentReasoning(true, `Verified placement guardrails for ${payload.sku}`);
              } else {
                setAgentReasoning(true, `Collision detected. Repositioning ${payload.sku}...`);
              }
              break;

            case 'scene_mutation':
              if (payload.action === 'ENTITY_ADDED') {
                const newEntity: ClientSpatialEntity = {
                  instanceId: payload.entity.instanceId,
                  catalogItemId: payload.entity.catalogItemId,
                  sku: payload.entity.sku,
                  name: payload.entity.name,
                  transform: payload.entity.transform,
                  boundingBox: payload.entity.boundingBox,
                  clearanceBufferMeters: payload.entity.clearanceBufferMeters,
                  isLocked: true,
                  isGhost: true,
                  assets: {
                    gltfUrl: payload.assets.gltf,
                    usdzUrl: payload.assets.usdz,
                  },
                };
                // Visual feedback: display ghost model immediately
                stageGhostEntity(newEntity);
              } else if (payload.action === 'LIGHTING_CHANGED') {
                updateLighting(payload.lighting);
              } else if (payload.action === 'SURFACE_MODIFIED') {
                applySurfaceModification({
                  planeAnchorId: payload.planeAnchorId,
                  surfaceType: 'wall',
                  pbrMaterial: payload.pbrMaterial,
                });
              }
              break;

            case 'commentary':
              setStreamCommentary((prev) => prev + payload.text);
              break;

            case 'done':
              // Commit ghost entities on stream completion
              useSceneStore.getState().entities.forEach((ent) => {
                if (ent.isGhost) {
                  commitGhostEntity(ent.instanceId);
                }
              });
              setAgentReasoning(false, null);
              break;

            case 'error':
              console.error('[Agent Stream Error Server Payload]:', payload);
              setAgentReasoning(false, null);
              break;
          }
        }
      }
    } catch (err) {
      console.error('[Agent Stream Consumer Fatal]:', err);
      setAgentReasoning(false, null);
    } finally {
      setIsStreaming(false);
    }
  }, [sessionId, stageGhostEntity, commitGhostEntity, updateLighting, applySurfaceModification, setAgentReasoning]);

  return { sendAgentMessage, isStreaming, streamCommentary };
}
