### 5. WebXR Photometric Light Estimator (`src/spatial/hooks/use-webxr-lighting.ts`)

Hooks directly into the native WebXR device Light Estimation API (`XRLightEstimate`) via R3F frame cycles. Reconciles real physical ambient intensity and spherical harmonics against design session lighting overrides.

```typescript
'use client';

import { useRef } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { useXR } from '@react-three/xr';
import * as THREE from 'three';
import { useSceneStore } from '@/src/spatial/store/scene-store';

export function useWebXRLighting() {
  const { gl } = useThree();
  const { session } = useXR();
  const lightProbeRef = useRef<THREE.LightProbe | null>(null);
  const directionalLightRef = useRef<THREE.DirectionalLight | null>(null);
  const xrLightProbeRequested = useRef(false);

  const lightingState = useSceneStore((s) => s.lighting);

  useFrame(() => {
    // If agent or user has explicitly overridden lighting, bypass WebXR physical estimate
    if (lightingState.overrideEnabled) {
      if (directionalLightRef.current && lightingState.directionalRig[0]) {
        const rig = lightingState.directionalRig[0];
        directionalLightRef.current.intensity = rig.intensity / 400; // Normalize Lux to Three.js units
        directionalLightRef.current.position.set(...rig.position);
      }
      return;
    }

    // WebXR Device Light Estimation API integration
    if (session && !xrLightProbeRequested.current) {
      try {
        const xrGlBinding = new (window as any).XRWebGLBinding(session, gl.getContext());
        session.requestLightProbe({ reflectionFormat: session.preferredReflectionFormat })
          .then((probe: any) => {
            xrLightProbeRequested.current = true;
            probe.addEventListener('estimation', (e: any) => {
              const estimate = e.data;
              if (estimate.sphericalHarmonicsCoefficients && lightProbeRef.current) {
                lightProbeRef.current.sh.fromArray(estimate.sphericalHarmonicsCoefficients);
              }
              if (estimate.primaryLightIntensity && estimate.primaryLightDirection && directionalLightRef.current) {
                const intensity = Math.max(estimate.primaryLightIntensity.x, estimate.primaryLightIntensity.y, estimate.primaryLightIntensity.z);
                directionalLightRef.current.intensity = intensity;
                directionalLightRef.current.position.set(
                  estimate.primaryLightDirection.x * 5,
                  estimate.primaryLightDirection.y * 5,
                  estimate.primaryLightDirection.z * 5
                );
              }
            });
          })
          .catch(() => {
            // Light probe estimation unsupported by underlying XR hardware
            xrLightProbeRequested.current = true;
          });
      } catch {
        xrLightProbeRequested.current = true;
      }
    }
  });

  return { lightProbeRef, directionalLightRef };
}
```

