### 6. Three.js / R3F Spatial Components

#### A. Metric Wall & Surface Mesh (`src/spatial/components/SurfacePlaneMesh.tsx`)

Renders architectural wall, floor, and ceiling planes detected during scanning, applying PBR materials with meter-scaled UV repeating.

```typescript
'use client';

import React, { useEffect, useState, useMemo } from 'react';
import * as THREE from 'three';
import { DetectedPlaneAnchor, ClientSurfaceModification } from '@/src/types/spatial-client';
import { assetPipeline } from '@/src/spatial/loaders/asset-pipeline';

interface SurfacePlaneMeshProps {
  plane: DetectedPlaneAnchor;
  modification?: ClientSurfaceModification;
}

export const SurfacePlaneMesh: React.FC<SurfacePlaneMeshProps> = ({ plane, modification }) => {
  const [albedoMap, setAlbedoMap] = useState<THREE.Texture | null>(null);

  const uvScale = useMemo<[number, number]>(() => {
    return modification?.pbrMaterial.uvScale || [plane.dimensions[0], plane.dimensions[1]];
  }, [modification, plane.dimensions]);

  useEffect(() => {
    let active = true;
    if (modification?.pbrMaterial.albedoMapUrl) {
      assetPipeline.loadPBRTexture(modification.pbrMaterial.albedoMapUrl, uvScale).then((tex) => {
        if (active) setAlbedoMap(tex);
      });
    } else {
      setAlbedoMap(null);
    }
    return () => {
      active = false;
    };
  }, [modification, uvScale]);

  const geometry = useMemo(() => {
    if (plane.boundaryPolygon && plane.boundaryPolygon.length >= 3) {
      const shape = new THREE.Shape();
      shape.moveTo(plane.boundaryPolygon[0][0], plane.boundaryPolygon[0][2]);
      for (let i = 1; i < plane.boundaryPolygon.length; i++) {
        shape.lineTo(plane.boundaryPolygon[i][0], plane.boundaryPolygon[i][2]);
      }
      shape.closePath();
      const geom = new THREE.ShapeGeometry(shape);
      geom.rotateX(Math.PI / 2); // Orient horizontal to vertical based on plane orientation
      return geom;
    }
    return new THREE.PlaneGeometry(plane.dimensions[0], plane.dimensions[1]);
  }, [plane]);

  const pbr = modification?.pbrMaterial;

  return (
    <mesh
      position={plane.transform.position}
      quaternion={plane.transform.rotation}
      scale={plane.transform.scale}
      geometry={geometry}
      receiveShadow
    >
      <meshStandardMaterial
        color={pbr?.albedoHex || (plane.semanticType === 'floor' ? '#2A2A2E' : '#E0E0E0')}
        map={albedoMap}
        roughness={pbr?.roughnessFactor ?? 0.8}
        metalness={pbr?.metallicFactor ?? 0.05}
        side={THREE.DoubleSide}
      />
    </mesh>
  );
};
```

#### B. Smooth 6DOF Entity Renderer with Ghost Support (`src/spatial/components/EntityRenderer.tsx`)

Renders placed GLB models. Handles smooth lerping and slerping between remote network ticks and optimistic manipulation ticks, displaying wireframe outlines when rendering LLM ghost previews.

```typescript
'use client';

import React, { useEffect, useRef, useState } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { ClientSpatialEntity } from '@/src/types/spatial-client';
import { assetPipeline } from '@/src/spatial/loaders/asset-pipeline';
import { useSceneStore } from '@/src/spatial/store/scene-store';

interface EntityRendererProps {
  entity: ClientSpatialEntity;
}

export const EntityRenderer: React.FC<EntityRendererProps> = ({ entity }) => {
  const groupRef = useRef<THREE.Group>(null);
  const [model, setModel] = useState<THREE.Group | null>(null);
  const [loadError, setLoadError] = useState(false);

  const selectedEntityId = useSceneStore((s) => s.selectedEntityId);
  const selectEntity = useSceneStore((s) => s.selectEntity);
  const isSelected = selectedEntityId === entity.instanceId;

  // Load Progressive Model via Pipeline
  useEffect(() => {
    let isMounted = true;
    assetPipeline
      .loadGLB(entity.assets.gltfUrl)
      .then((loadedGroup) => {
        if (isMounted) {
          setModel(loadedGroup);
        }
      })
      .catch((err) => {
        console.error(`[EntityRenderer] Model load error for SKU ${entity.sku}:`, err);
        if (isMounted) setLoadError(true);
      });

    return () => {
      isMounted = false;
    };
  }, [entity.assets.gltfUrl, entity.sku]);

  // Handle Interpolation (Lerp / Slerp) for remote actions
  useFrame((_, delta) => {
    if (!groupRef.current) return;

    if (entity.targetTransform && !entity.isLocked) {
      const targetPos = new THREE.Vector3(...entity.targetTransform.position);
      const targetRot = new THREE.Quaternion(...entity.targetTransform.rotation);

      // Lerp Position
      groupRef.current.position.lerp(targetPos, Math.min(1, delta * 14));
      // Slerp Quaternion
      groupRef.current.quaternion.slerp(targetRot, Math.min(1, delta * 14));
    } else {
      // Direct optimistic placement
      groupRef.current.position.set(...entity.transform.position);
      groupRef.current.quaternion.set(...entity.transform.rotation);
      groupRef.current.scale.set(...entity.transform.scale);
    }
  });

  return (
    <group
      ref={groupRef}
      onClick={(e) => {
        e.stopPropagation();
        if (!entity.isGhost) {
          selectEntity(isSelected ? null : entity.instanceId);
        }
      }}
    >
      {model && <primitive object={model} />}

      {/* Fallback Mesh on Load Error */}
      {loadError && (
        <mesh position={[0, entity.boundingBox.extents[1], 0]}>
          <boxGeometry args={[entity.boundingBox.extents[0] * 2, entity.boundingBox.extents[1] * 2, entity.boundingBox.extents[2] * 2]} />
          <meshStandardMaterial color="#FF3366" wireframe />
        </mesh>
      )}

      {/* Visual Indicator: LLM Ephemeral Ghost Preview */}
      {entity.isGhost && (
        <mesh position={[0, entity.boundingBox.extents[1], 0]}>
          <boxGeometry args={[entity.boundingBox.extents[0] * 2, entity.boundingBox.extents[1] * 2, entity.boundingBox.extents[2] * 2]} />
          <meshBasicMaterial color="#00E5FF" wireframe transparent opacity={0.4} />
        </mesh>
      )}

      {/* Selection Bounding Wireframe */}
      {isSelected && (
        <mesh position={[0, entity.boundingBox.extents[1], 0]}>
          <boxGeometry
            args={[
              entity.boundingBox.extents[0] * 2 + 0.04,
              entity.boundingBox.extents[1] * 2 + 0.04,
              entity.boundingBox.extents[2] * 2 + 0.04,
            ]}
          />
          <meshBasicMaterial color="#FFCC00" wireframe />
        </mesh>
      )}
    </group>
  );
};
```

#### C. WebXR 6DOF Controller & Gizmo Interactor (`src/spatial/components/TransformManipulator.tsx`)

Bridges 6DOF WebXR Controllers, pinching hand-gestures, and desktop pointer gizmos back to the state store, triggering network broadcasts upon manipulation release.

```typescript
'use client';

import React, { useRef } from 'react';
import { useThree } from '@react-three/fiber';
import { TransformControls } from '@react-three/drei';
import { useSceneStore } from '@/src/spatial/store/scene-store';
import { useSceneGraphSync } from '@/src/spatial/hooks/use-scene-graph-sync';
import { Transform3D } from '@/src/types/spatial-client';

export const TransformManipulator: React.FC = () => {
  const transformRef = useRef<any>(null);
  const { scene } = useThree();

  const selectedEntityId = useSceneStore((s) => s.selectedEntityId);
  const sessionId = useSceneStore((s) => s.sessionId);
  const activeGizmoMode = useSceneStore((s) => s.activeGizmoMode);
  const updateEntityTransformOptimistic = useSceneStore((s) => s.updateEntityTransformOptimistic);
  const setEntityLock = useSceneStore((s) => s.setEntityLock);

  const { broadcastLocalTransform, broadcastReleaseTransform } = useSceneGraphSync(sessionId);

  if (!selectedEntityId || activeGizmoMode === 'none') {
    return null;
  }

  return (
    <TransformControls
      ref={transformRef}
      mode={activeGizmoMode}
      onMouseDown={() => {
        setEntityLock(selectedEntityId, true, 'user');
      }}
      onChange={() => {
        if (!transformRef.current || !transformRef.current.object) return;
        const obj = transformRef.current.object;

        const currentTransform: Transform3D = {
          position: [obj.position.x, Math.max(0, obj.position.y), obj.position.z], // Clamp furniture to floor level
          rotation: [obj.quaternion.x, obj.quaternion.y, obj.quaternion.z, obj.quaternion.w],
          scale: [obj.scale.x, obj.scale.y, obj.scale.z],
        };

        // 1. Local Optimistic Update
        updateEntityTransformOptimistic(selectedEntityId, currentTransform);
        // 2. High-Frequency Realtime Peer Sync
        broadcastLocalTransform(selectedEntityId, currentTransform);
      }}
      onMouseUp={() => {
        setEntityLock(selectedEntityId, false);
        broadcastReleaseTransform(selectedEntityId);
      }}
    />
  );
};
```

