### 7. Primary Spatial Canvas Entrypoint (`src/spatial/components/SpatialCanvas.tsx`)

Coordinates the WebXR Canvas, photometric lighting, procedural architectural surfaces, dynamic entities, and the user-agent interaction loop.

```typescript
'use client';

import React, { Suspense, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { VRButton, ARButton, XR, Controllers, Hands } from '@react-three/xr';
import * as THREE from 'three';
import { useSceneStore } from '@/src/spatial/store/scene-store';
import { useWebXRLighting } from '@/src/spatial/hooks/use-webxr-lighting';
import { SurfacePlaneMesh } from '@/src/spatial/components/SurfacePlaneMesh';
import { EntityRenderer } from '@/src/spatial/components/EntityRenderer';
import { TransformManipulator } from '@/src/spatial/components/TransformManipulator';
import { assetPipeline } from '@/src/spatial/loaders/asset-pipeline';

function SpatialSceneContainer() {
  const planes = useSceneStore((s) => Array.from(s.planes.values()));
  const entities = useSceneStore((s) => Array.from(s.entities.values()));
  const surfaceModifications = useSceneStore((s) => s.surfaceModifications);
  const lighting = useSceneStore((s) => s.lighting);

  const { lightProbeRef, directionalLightRef } = useWebXRLighting();

  return (
    <>
      {/* Light Estimator and Dynamic Rigs */}
      <lightProbe ref={lightProbeRef as any} />
      <ambientLight
        color={new THREE.Color(...lighting.ambientLightColor)}
        intensity={lighting.ambientIntensity / 1000}
      />
      <directionalLight
        ref={directionalLightRef as any}
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
        shadow-bias={-0.0001}
      />

      {/* Structural Room Scan Surfaces */}
      {planes.map((plane) => (
        <SurfacePlaneMesh
          key={plane.id}
          plane={plane}
          modification={surfaceModifications.get(plane.id)}
        />
      ))}

      {/* Dynamically Populated 3D Furniture Entities */}
      {entities.map((entity) => (
        <EntityRenderer key={entity.instanceId} entity={entity} />
      ))}

      {/* 6DOF Interaction Gizmos */}
      <TransformManipulator />
    </>
  );
}

interface SpatialCanvasProps {
  sessionId: string;
}

export const SpatialCanvas: React.FC<SpatialCanvasProps> = ({ sessionId }) => {
  const setXRActive = useSceneStore((s) => s.setXRActive);
  const setClientRuntime = useSceneStore((s) => s.setClientRuntime);

  useEffect(() => {
    // Detect Apple Vision Pro Safari Runtime
    const isVisionOS = navigator.userAgent.includes('Macintosh') && 'ontouchend' in document;
    if (isVisionOS) {
      setClientRuntime('VisionOS');
    }
  }, [setClientRuntime]);

  return (
    <div className="relative w-full h-full min-h-screen bg-neutral-950 overflow-hidden select-none">
      {/* WebXR Entry Buttons */}
      <div className="absolute top-4 right-4 z-50 flex gap-2">
        <ARButton
          sessionInit={{
            requiredFeatures: ['hit-test', 'plane-detection'],
            optionalFeatures: ['light-estimation', 'mesh-detection', 'hand-tracking'],
          }}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white font-medium rounded-lg shadow-lg"
        />
      </div>

      <Canvas
        shadows
        gl={{
          antialias: true,
          alpha: true,
          powerPreference: 'high-performance',
        }}
        camera={{ position: [0, 1.6, 2], fov: 65 }}
        onCreated={({ gl }) => {
          assetPipeline.initKTX2(gl);
        }}
      >
        <XR
          onSessionStart={() => setXRActive(true)}
          onSessionEnd={() => setXRActive(false)}
        >
          <Controllers />
          <Hands />
          <Suspense fallback={null}>
            <SpatialSceneContainer />
          </Suspense>
        </XR>
      </Canvas>
    </div>
  );
};
